#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Kiln's signed updates and releases.
# Run from anywhere: ./scripts/setup-updates.sh
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

# gh writes secrets and variables to the repository it finds here.
cd "$(dirname "$0")/.."
REPO="MaxB-Coder/kiln"
KEY_DIR="$HOME/.kiln-release"
KEY_FILE="$KEY_DIR/kiln-update.key"
ENDPOINT="https://github.com/$REPO/releases/latest/download/latest.json"

banner "Kiln: signed updates and releases"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check the tools"
say "Kiln's updater only installs files signed with your key. This wizard makes"
say "that key, stores it where the release workflow can use it, and turns on releases."
if ! gh auth status >/dev/null 2>&1; then
  warn "gh isn't logged in. Run: gh auth login   then start this wizard again."
  exit 1
fi
if ! cargo packager --version >/dev/null 2>&1; then
  warn "cargo-packager is missing. Run: cargo install cargo-packager --version 0.11.8 --locked"
  exit 1
fi
visibility=$(gh repo view "$REPO" --json visibility --jq .visibility)
say "gh is logged in, cargo-packager is installed, and $REPO is $(printf '%s' "$visibility" | tr '[:upper:]' '[:lower:]')."
if [[ "$visibility" != "PUBLIC" ]]; then
  warn "The updater downloads release files without a login, so the repository must be public."
  exit 1
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Choose a password for the key"
say "The key file is encrypted with this password. You'll save both in your"
say "password manager in stage 5, and GitHub keeps a copy for the release workflow."
KEY_PASSWORD=""
while true; do
  ask_secret KEY_PASSWORD "New password (16+ characters):"
  ask_secret KEY_PASSWORD_AGAIN "Same password again:"
  if [[ ${#KEY_PASSWORD} -lt 16 ]]; then
    warn "That's shorter than 16 characters. Try again."
  elif [[ "$KEY_PASSWORD" != "$KEY_PASSWORD_AGAIN" ]]; then
    warn "The two don't match. Try again."
  else
    break
  fi
done
unset KEY_PASSWORD_AGAIN

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Generate the signing key"
if [[ -f "$KEY_FILE" ]]; then
  warn "A key already exists at $KEY_FILE."
  say "Installed copies of Kiln trust that key, so replacing it would cut them off"
  say "from updates. This wizard keeps it and uses it as it is."
  note "(Use the password it was made with in stage 2.)"
else
  mkdir -p "$KEY_DIR" && chmod 700 "$KEY_DIR"
  cargo packager signer generate --ci --path "$KEY_FILE" --password "$KEY_PASSWORD" >/dev/null
  chmod 600 "$KEY_FILE" "$KEY_FILE.pub"
  printf '  %s✓ made%s %s and %s.pub\n' "$GREEN" "$RESET" "$KEY_FILE" "$KEY_FILE"
fi
say "Public key (safe to share; it goes into every Kiln build):"
note "$(cat "$KEY_FILE.pub")"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Store it in GitHub"
say "Secrets are encrypted by GitHub and only readable by workflows; variables are public."
set_secret KILN_UPDATE_PRIVATE_KEY "$(cat "$KEY_FILE")"
set_secret KILN_UPDATE_PRIVATE_KEY_PASSWORD "$KEY_PASSWORD"
set_var KILN_UPDATE_PUBKEY "$(cat "$KEY_FILE.pub")"
set_var KILN_UPDATE_ENDPOINT "$ENDPOINT"
say ""
say "Weekly releases: every Monday 06:00 UTC the release workflow builds, tests and"
say "publishes installers for macOS, Windows and Linux, and your installed Kiln updates."
if confirm "Turn on weekly releases?"; then
  set_var KILN_RELEASES on
else
  note "Left off. Turn on later with: gh variable set KILN_RELEASES --body on"
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Back up the key"
say "GitHub never shows a secret again, so this backup is the only way to get the key"
say "back (for example to move releases elsewhere). Without it no future update can be"
say "signed for the copies already installed."
step "In your password manager, make a new secure note called \"Kiln update key\"."
step "Paste the password from stage 2."
step "Paste the whole key file. It's opened in Finder for you: $KEY_FILE"
open_url "$KEY_DIR"
pause "Press Enter once the key and password are saved"
if confirm "Delete the local copy of the private key now (the .pub stays)?"; then
  rm -P "$KEY_FILE" 2>/dev/null || rm -f "$KEY_FILE"
  printf '  %s✓ deleted%s %s\n' "$GREEN" "$RESET" "$KEY_FILE"
else
  note "Kept at $KEY_FILE (readable only by you)."
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Publish the first release"
say "The release workflow builds and tests all three installers, then publishes them"
say "with latest.json, so copies installed from it can update themselves."
if confirm "Start the first published release now?"; then
  gh workflow run release.yml --repo "$REPO" -f publish=true
  printf '  %s✓ started%s the release workflow\n' "$GREEN" "$RESET"
  open_url "https://github.com/$REPO/actions/workflows/release.yml"
  note "It takes about 30 minutes. The release appears at https://github.com/$REPO/releases"
else
  note "Start it later with: gh workflow run release.yml -f publish=true"
fi
unset KEY_PASSWORD
pause

finish
